#pragma once

#include <QIcon>
#include <QString>
#include <QStringList>
#include <vector>

class QWidget;

// Database icons ("Databases" panel, right-click → Change icon):
// about a hundred line drawings sorted by theme, taken from Lucide (ISC licence).
// The table is generated by tools/make_base_icons.py into baseicons.inc.
namespace baseicons {

inline constexpr char DefaultId[] = "database";

struct Entry {
    const char* id;   // identifier stored in the settings (Lucide name)
    int theme;        // index into themes()
    const char* body; // 24×24 SVG drawing
};
const std::vector<Entry>& entries();
QStringList themes();

// Icon from its identifier; empty or unknown: the default icon.
QIcon icon(const QString& id);

// Icon chosen for a database (by file path), kept in the settings.
QString chosen(const QString& path);
void setChosen(const QString& path, const QString& id);

// Chooser dialog. Returns false if cancelled; otherwise `id` receives the chosen icon.
bool choose(QWidget* parent, const QString& baseName, QString* id);

} // namespace baseicons
